INSERT INTO surveys ("id", "session_id", "participant_id", "scenario_id", "perceived_helpfulness", "support_amount", "ai_helped_discussion", "ai_helped_focus", "ai_helped_inclusion", "ai_helped_disagreement", "collaboration_rating", "shared_answer_rating", "autonomy_rating", "ai_helped_thinking", "over_reliance_rating", "could_answer_without_ai", "satisfaction_rating", "open_reflection", "answer_confidence", "confidence_reason", "do_differently", "created_at") VALUES ('51fe97b8-c486-49f3-ac86-fb24d7e4595a', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'e2aa0a78-5366-4e64-aba2-176f3dd67eae', 'scenario-10', NULL, NULL, NULL, NULL, NULL, NULL, 2, 2, 3, NULL, NULL, NULL, 3, 'I did not open the AI. The person who did said the hint was useless.', 2, 'I did not really write it, so I am only slightly confident.', 'Start with the explanation earlier, not only on the last tasks.', '2026-10-30T09:00:11.000Z');
