INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('aca7753f-a137-4613-a1b8-2b0d72e02f2e', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'f5d385d9-9bfb-4fcd-abd3-9015bcf67371', 'post', '{"post-1":2,"post-2":0,"post-3":3,"post-4":0,"post-5":0,"post-6":1,"post-7":0,"post-8":0}', '{"open_collaboration":"Collaborative means we talk and everyone can explain the answer, not only split the pages.","open_ai_role":"AI can give the answer but the group should still say it in our own words. We did not always do that."}', 5, 8, '2026-10-30T09:03:51.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('2c2929e9-1ae8-4980-a1ce-7a6a9bc2e339', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'f5d385d9-9bfb-4fcd-abd3-9015bcf67371', 'assessment_completed', '{"assessmentType":"post","score":5,"maxScore":8}', '2026-10-30T09:03:51.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('b594f2c3-eecd-4852-a908-1d233457633c', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'f5d385d9-9bfb-4fcd-abd3-9015bcf67371', '{"ai_effect_on_collaboration":"We waited for the full answer and then I wrote a shorter version. We did not talk much.","most_useful_support":"The full expert answer. I knew what to write after that.","unhelpful_or_too_much":"Small hints. They never told us what the answer was.","thinking_and_reliance":"Yes. On most tasks the AI did the thinking and I shortened it.","ai_into_group_answer":"Yes. I put the AI answer into the group box in fewer words.","private_vs_shared_ai":"Private was fine, because I was the one using it.","participation":"Not really. I wrote almost every answer. The others mostly agreed.","agreement_on_answer":"I clicked I am good because it matched the AI, not because we had debated it.","learned_most":"Group work is more than splitting, but we still handed the thinking to the AI.","suggested_changes":"Hints are not enough for people like us. The full answer is what we actually used."}', '2026-10-30T09:07:51.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('55c25c71-0e8c-4943-a13d-ef91a8d24663', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'f5d385d9-9bfb-4fcd-abd3-9015bcf67371', 'final_reflection_submitted', 'null', '2026-10-30T09:07:51.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('0228b23b-20fe-42fa-a24a-93e05bf2640d', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', '91390e8f-1cb7-40e9-a332-9b813760d430', 'post', '{"post-1":2,"post-2":2,"post-3":1,"post-4":1,"post-5":0,"post-6":1,"post-7":3,"post-8":2}', '{"open_collaboration":"We have to discuss and agree, not just join parts. Otherwise one person writes and the others dont know it.","open_ai_role":"Use the AI for the idea, then change the words. A full answer is easy to copy."}', 4, 8, '2026-10-30T09:05:51.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('b5ac246e-a09c-430c-a173-44d80a3537b7', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', '91390e8f-1cb7-40e9-a332-9b813760d430', 'assessment_completed', '{"assessmentType":"post","score":4,"maxScore":8}', '2026-10-30T09:05:51.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('d82d4434-7026-42f9-afcd-6f71c82a118e', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', '91390e8f-1cb7-40e9-a332-9b813760d430', '{"ai_effect_on_collaboration":"It made us finish fast. We stopped discussing once the full answer appeared.","most_useful_support":"Full expert answer, on the judgement tasks.","unhelpful_or_too_much":"The minimal hint. I opened it once and it did not help.","thinking_and_reliance":"Often, yes. We were satisfied with the AI text and did not add much.","ai_into_group_answer":"Panagiotis did that most times. I did it on the due-tomorrow task.","private_vs_shared_ai":"Shared would have been ok too. Only one of us was reading it anyway.","participation":"No. Two of us typed on a couple of tasks, and all three only once or twice.","agreement_on_answer":"I clicked I am good so we could move on. I had not checked every sentence.","learned_most":"Copying a correct answer is not the same as learning it. My post-test was better but still shaky.","suggested_changes":"Dont offer such a small hint. It feels like no help."}', '2026-10-30T09:08:51.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('f5a69287-94e1-4bad-acb0-6d388e005717', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', '91390e8f-1cb7-40e9-a332-9b813760d430', 'final_reflection_submitted', 'null', '2026-10-30T09:08:51.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('dcff2ec4-333a-4b7f-aa0e-028cf4328bb5', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'e2aa0a78-5366-4e64-aba2-176f3dd67eae', 'post', '{"post-1":0,"post-2":0,"post-3":3,"post-4":1,"post-5":0,"post-6":0,"post-7":0,"post-8":1}', '{"open_collaboration":"Group work is better if we all say something about the same answer.","open_ai_role":"Ask the AI when we are stuck, then check if we agree before we submit."}', 4, 8, '2026-10-30T09:07:51.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('aed80083-e7fe-493d-a42c-989d2a7e520a', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'e2aa0a78-5366-4e64-aba2-176f3dd67eae', 'assessment_completed', '{"assessmentType":"post","score":4,"maxScore":8}', '2026-10-30T09:07:51.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('e6787925-108f-486d-abcc-6bb5c2fe1bb3', 'df6d898f-2edb-4e44-a67b-9da422dba0b5', 'e2aa0a78-5366-4e64-aba2-176f3dd67eae', '{"ai_effect_on_collaboration":"I mostly waited. The AI answer showed up and someone else typed it.","most_useful_support":"I did not use much. The full answer the others got was the useful one.","unhelpful_or_too_much":"Hints. I saw one and it did not say the answer.","thinking_and_reliance":"Yes for the group. I could not have written those answers alone at the start.","ai_into_group_answer":"Only a little, on the task where we each added one line.","private_vs_shared_ai":"Shared, so I can see what they are reading.","participation":"I did not contribute on most answers. I said ok in the chat.","agreement_on_answer":"I clicked I am good because they were already done, not because I was sure.","learned_most":"I can say now that splitting pages is not real collaboration. I left the first written questions blank because I did not know.","suggested_changes":"Give the full answer earlier and say it more simply."}', '2026-10-30T09:09:51.000Z');
