INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('05f58cec-c89e-4749-aea2-6d1a74f326dc', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-01', 1, 'Collaborative learning means the group builds a shared understanding, not just dividing the assignment into separate parts. It hurts learning when nobody can explain the other parts. In our lab report last term each person wrote one section and the presentation fell apart, because we had never questioned each other''s sections. So every member should be able to explain the result in everyday words. If only one person understands it, the group did not learn it together.', '[{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":124},{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":205},{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":143}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'a74f0b42-e6cc-4be4-a350-007a229019b8', '2026-11-01T08:38:48.000Z', '2026-11-01T08:49:58.000Z', 1, '2026-11-01T08:38:48.000Z', '2026-11-01T08:49:58.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('7dfdc97f-c37f-47d2-ae47-6eaa678352b1', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-01","scenarioOrder":1}', '2026-11-01T08:38:48.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('d0dd1582-f8a7-4ac9-a73b-01540f6c10bc', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 1, 'I think collaborative means we build one answer together, not divide chapters.', '2026-11-01T08:39:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('ab55274e-e6f2-4f11-aba5-f6f87fc2a0aa', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 1, 'Dividing is faster though. When does it actually hurt learning?', '2026-11-01T08:40:18.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('4fa81773-6382-44d4-acb8-6ca01b8de15e', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 1, 'When nobody can explain the other parts.', '2026-11-01T08:41:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('5d734601-7a00-4d55-af96-69a739a9cf57', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 1, 'Should we look at a full answer just to compare?', '2026-11-01T08:42:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('6e03882c-c28f-4a30-aad6-c4ab9ef6bb7d', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 1, 'It is almost the whole answer. Lets keep our own example and not copy all of it.', '2026-11-01T08:45:48.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('a20392ab-c696-4bae-a482-2a24a90f31bf', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 1, 'I added the part about explaining it back.', '2026-11-01T08:46:38.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('6045cb76-45d7-48f0-abb5-57a55b017129', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 1, 'full_answer', 'Collaborative learning means the group builds a shared understanding and every member can explain the result. Dividing the assignment into separate parts only looks efficient. A clear example is a lab report where each person writes one section and nobody can present the whole study.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 1. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1700, 1, 1, 0, '2026-11-01T08:43:28.000Z', '2026-11-01T08:43:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('5510dd64-55af-476a-af0a-51634fa18b92', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'ai_support_requested', '{"scenarioOrder":1,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":1700}', '2026-11-01T08:43:29.700Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('2b079fd4-537f-4922-ad53-b0a613456885', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 1, 'finalAnswer', 124, 12, 'Collaborative learning means the group builds a shared understanding, not just dividing the assignment into separate parts.', '2026-11-01T08:45:23.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('70e3653c-54c1-48b4-a900-5853fbae75e8', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 1, 'finalAnswer', 205, 0, 'It hurts learning when nobody can explain the other parts. In our lab report last term each person wrote one section and the presentation fell apart, because we had never questioned each other''s sections.', '2026-11-01T08:46:08.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('d3db544f-18b5-4c02-a885-b977654d0366', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 1, 'finalAnswer', 143, 0, 'So every member should be able to explain the result in everyday words. If only one person understands it, the group did not learn it together.', '2026-11-01T08:46:53.000Z');
