INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('68e795fa-d1e1-45a2-a27c-0bcb1909e90c', '05f58cec-c89e-4749-aea2-6d1a74f326dc', 'final', 'P. Palat', 3, 3, 2, 3, 2, 2, 'Shared answer (15/24). Clear, but several phrases come from the full AI answer.', '2026-11-02T10:49:58.000Z', '2026-11-02T10:49:58.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('0dd726d0-e166-411d-a219-91a8f230bfca', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-02', 2, 'Faster work is not the same as learning. The sentence misses explaining ideas, challenging assumptions and shared responsibility. Splitting the work reduces learning when nobody has to defend what the others produced, so a weak member can hide inside a finished page. We would revise it to: group work is useful when the group thinks together and every person can explain the result, not when the page is finished sooner.', '[{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":130},{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":138},{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":153}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'a74f0b42-e6cc-4be4-a350-007a229019b8', '2026-11-01T08:53:08.000Z', '2026-11-01T09:04:38.000Z', 1, '2026-11-01T08:53:08.000Z', '2026-11-01T09:04:38.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('4455da30-3b21-4e51-a9e9-6d2ce70c473e', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-02","scenarioOrder":2}', '2026-11-01T08:53:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('5ef1cdac-6785-46c3-a076-16fd7e22cd1d', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 2, 'The weak answer only mentions speed. That feels too small.', '2026-11-01T08:53:43.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('2197b1e3-d855-4eca-a0ab-4a75295788b0', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 2, 'Missing: we learn by explaining, and someone can hide if we only split.', '2026-11-01T08:54:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('08759408-c86d-4621-ac48-89ea4050fb39', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 2, 'I want the full answer to see what we missed.', '2026-11-01T08:55:18.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('8378159f-18ea-47e9-a5d9-d6752f9f088f', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 2, 'This full answer is too revealing. It basically wrote our revision.', '2026-11-01T08:59:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('891fecb1-8967-4ca8-ae97-a1afd09eb285', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 2, 'Lets use the missing benefits but write the revision ourselves.', '2026-11-01T09:00:18.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('e8b43143-cf08-4b0e-a143-42cf7aacdb43', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 2, 'full_answer', 'The sentence is misleading because faster work is not the same as learning. Missing benefits are explaining ideas, challenging assumptions and shared responsibility. Splitting the work reduces learning when members never have to defend or revise what the others produced. A better answer would say group work is useful when the group thinks together, not when the page is finished sooner.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 2. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 2000, 1, 1, 0, '2026-11-01T08:56:28.000Z', '2026-11-01T08:56:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('a2206c87-2df9-4956-a6cc-cf9a90425a67', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 'ai_support_requested', '{"scenarioOrder":2,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":2000}', '2026-11-01T08:56:30.000Z');
