INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('b2a5d40d-af11-4d0c-a06e-7ba75911f457', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-03', 3, 'We recommend peer assessment of contributions together with assigned roles, not instead of them. The quiz checks learning but it does not fix who does the work. Roles stop one member from taking every decision. The risk is that friends rate each other kindly, so the criteria have to be public. We are not only copying the model answer here.', '[{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":97},{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":114},{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":130}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'e061052e-750f-4d10-a72e-cfe57e002a3a', '2026-11-01T09:07:48.000Z', '2026-11-01T09:20:18.000Z', 1, '2026-11-01T09:07:48.000Z', '2026-11-01T09:20:18.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('91bab028-6b9d-4904-a04c-cc0acddea9a5', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-03","scenarioOrder":3}', '2026-11-01T09:07:48.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('2d92374c-58c6-4f7e-a790-3b8140ffd817', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 3, 'Free-rider and someone who takes over. Three options.', '2026-11-01T09:08:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('bde7037d-ceb4-4bb1-aa3e-42fd2a9f511c', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 3, 'Peer assessment makes the free-rider visible, but it can become a popularity vote.', '2026-11-01T09:09:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('77a14861-4056-4286-a78c-a3073bd62ee8', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 3, 'Roles might force the quiet person to speak. A quiz checks if we all learned.', '2026-11-01T09:10:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('5a1113f3-4272-4b8f-a071-3d43ac2a2d1a', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 3, 'I still want a full model so we can compare our choice.', '2026-11-01T09:11:38.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('0cb20ce2-008d-40ba-a873-65321f79426a', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 3, 'The model picked peer assessment too quickly. I want the trade-off left in.', '2026-11-01T09:15:48.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('011f440b-c283-442b-a162-ced8bad102b7', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 3, 'full_answer', 'Recommend peer assessment of contributions, with assigned roles as a support. An individual quiz checks learning but does not fix the process. Peer assessment makes unequal work visible, while roles stop one member from taking every decision. The risk is that friends rate each other kindly.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 3. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1800, 1, 1, 0, '2026-11-01T09:12:48.000Z', '2026-11-01T09:12:52.000Z');
