INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('dc4a3885-2088-4239-adf2-1e4aad1d5e94', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-04', 4, 'It is not acceptable to submit a full AI answer the group has not understood. The grade would describe the AI, not what we can explain. Time pressure explains why someone would do it the night before, but it does not justify skipping the learning or hiding the tool from the teacher. We would allow a full AI answer only as a comparison after we had already written our own position on honesty, fairness and what each member actually did.', '[{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":136},{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":148},{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":154}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'a74f0b42-e6cc-4be4-a350-007a229019b8', '2026-11-01T09:23:28.000Z', '2026-11-01T09:35:38.000Z', 1, '2026-11-01T09:23:28.000Z', '2026-11-01T09:35:38.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('01b07755-1854-4cf8-a1ef-ed5e49107f9e', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-04","scenarioOrder":4}', '2026-11-01T09:23:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('a439a789-a1e2-4d26-ad55-9a2505a6cbf8', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 4, 'Due tomorrow. One member wants to submit a full AI answer and read it later.', '2026-11-01T09:23:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('e88052bb-78a9-4bf0-a52c-c809fe840933', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 4, 'I get the time pressure, but then none of us learned it.', '2026-11-01T09:24:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('2b5fc741-9852-43f8-abb6-1caabecd2ebc', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 4, 'Honesty matters, and it is unfair if other groups actually did the work.', '2026-11-01T09:25:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('483d73d3-32d9-4252-a3e3-8ba042e64c1a', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 4, 'Lets see the expert version, then decide how strong we want to be.', '2026-11-01T09:27:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('8ebdb088-7312-4ce3-ae7e-b11c2bfcf34f', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 4, 'Too revealing again. It gave the conclusion and the conditions. We should keep our own line on time pressure.', '2026-11-01T09:31:08.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('679b9d58-2539-4b0d-a692-b838582d8268', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 4, 'full_answer', 'It is not acceptable to submit a full AI answer the group has not understood. Time pressure explains the temptation but does not justify it. A full AI answer is justified only as a comparison after the group has written its own position on learning, honesty and fairness.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 4. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1600, 1, 1, 0, '2026-11-01T09:28:08.000Z', '2026-11-01T09:28:12.000Z');
