INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('e4160e4a-a951-484d-af67-f7518791a06e', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-05', 5, 'Best means learning and fair participation, not the least effort. We listed those criteria before comparing. A shared document with edit history makes participation visible, and the decision stays with us. Roles help the talk, and an AI assistant is useful later, but this activity showed it can take over if it is the first support. So we prioritise the shared document.', '[{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":109},{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":97},{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":165}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'a74f0b42-e6cc-4be4-a350-007a229019b8', '2026-11-01T09:38:48.000Z', '2026-11-01T09:50:18.000Z', 1, '2026-11-01T09:38:48.000Z', '2026-11-01T09:50:18.000Z');
