INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('0c3f2337-b4a3-4059-ad94-7b6f4ec99461', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 5, 'No full answer this time. We already saw that it writes the conclusion for us.', '2026-11-01T09:39:28.000Z');
