INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('4c0aa49d-de20-45e5-a5ed-7c29f4e864c0', '2152bebe-763d-41d0-ae28-02267c83108e', 'final', 'P. Palat', 4, 3, 3, 3, 3, 3, 'Shared answer (19/24). More of the group''s own reasoning as the AI help gets lighter.', '2026-11-02T12:04:18.000Z', '2026-11-02T12:04:18.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('4b878878-428f-4367-a89b-8ba109917989', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-07', 7, 'We would restrict AI, not ban it and not leave it unrestricted. Unrestricted use lets a group submit a report no member engaged with, and a ban also blocks useful questions. The line is questions and feedback, not a finished report. A rule we cannot see being broken will not change what groups do, so the group should be able to show its draft history. Evidence the group still thought: we can explain the answer without the AI window open.', '[{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":174},{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":180},{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":87}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'a74f0b42-e6cc-4be4-a350-007a229019b8', '2026-11-01T10:07:28.000Z', '2026-11-01T10:19:18.000Z', 1, '2026-11-01T10:07:28.000Z', '2026-11-01T10:19:18.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('f9fa738e-25a7-485e-ae50-c727e04e2a4e', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-07","scenarioOrder":7}', '2026-11-01T10:07:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('1d61b139-c7a7-4601-a4ac-bd0417c757a5', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 7, 'Allow, restrict or ban. I dont want a full answer, we know that pattern now.', '2026-11-01T10:07:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('9cc914a4-ce5c-42d1-ab1a-1f9a10c27987', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 7, 'Unrestricted means a report no one engaged with. A ban also blocks useful questions.', '2026-11-01T10:08:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('c3201fe2-a011-4258-a388-e49abb26e755', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 7, 'Restrict: say what the AI may be used for.', '2026-11-01T10:10:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('9dde582f-a13a-48fc-a4a8-0002eec7cbdb', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 7, 'A hint and a question only, please.', '2026-11-01T10:11:18.000Z');
