INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('5c9e3ea7-bff1-453a-a315-61c096d34ea9', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 7, 'guiding_question', 'If AI is allowed only for questions and feedback, what evidence would show a group had still done the thinking?', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 7. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1000, 1, 1, 0, '2026-11-01T10:12:48.000Z', '2026-11-01T10:12:52.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('ffc22ca4-3f06-4b55-adb7-b77bbf59b731', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'ai_support_requested', '{"scenarioOrder":7,"scaffoldingType":"guiding_question","mocked":false,"model":"gpt-6-luna","latencyMs":1000}', '2026-11-01T10:12:49.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('11340c97-7d16-4273-a636-78936cb9ead0', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 7, 'finalAnswer', 174, 12, 'We would restrict AI, not ban it and not leave it unrestricted. Unrestricted use lets a group submit a report no member engaged with, and a ban also blocks useful questions.', '2026-11-01T10:14:03.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('13a546f2-41cc-4455-a8ba-aed1e5ce4f1c', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 7, 'finalAnswer', 180, 0, 'The line is questions and feedback, not a finished report. A rule we cannot see being broken will not change what groups do, so the group should be able to show its draft history.', '2026-11-01T10:14:48.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('79844c13-17e8-43f1-a9b3-37a4b91d72e3', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 7, 'finalAnswer', 87, 0, 'Evidence the group still thought: we can explain the answer without the AI window open.', '2026-11-01T10:15:33.000Z');
