INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('ace4bc83-cc9e-4931-ae47-840eb155ffda', '4b878878-428f-4367-a89b-8ba109917989', 'final', 'P. Palat', 4, 3, 3, 3, 3, 3, 'Shared answer (19/24). More of the group''s own reasoning as the AI help gets lighter.', '2026-11-02T12:19:18.000Z', '2026-11-02T12:19:18.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('ed1b895c-420f-4bff-a33b-32a9086ed110', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-08', 8, 'The 12% is an association, not proof that group work caused the higher score. The study does not say the groups were formed at random. Students who chose groups may already have been stronger or more motivated, so we would need their earlier scores before calling this an effect of collaboration. The 45% who called the workload unfair show that the average hides unequal participation. We would also want each member''s contribution, not only the group exam score.', '[{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":135},{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":162},{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":167}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'e9921b84-b421-4810-a448-41ac4fa961a3', '2026-11-01T10:22:28.000Z', '2026-11-01T10:33:58.000Z', 1, '2026-11-01T10:22:28.000Z', '2026-11-01T10:33:58.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('878199c0-8347-44fd-a9ca-a89f81eb31e4', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-08","scenarioOrder":8}', '2026-11-01T10:22:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('8ed00526-8123-4771-ac3b-f6652a635e11', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 8, '12% higher, but 45% called the workload unfair. I dont want to jump.', '2026-11-01T10:23:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('1baa811e-9a1d-4faa-a96b-f6cd1a859602', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 8, 'Maybe stronger students chose groups. That would raise the score without the group teaching them.', '2026-11-01T10:24:18.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('aaccdaee-08a3-400f-a3e8-02bb2cc0d70f', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 8, 'And the 45% means the average hides who did the work.', '2026-11-01T10:25:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('3d7fbf77-05b1-4a09-a604-ece40edb8d0e', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 8, 'One guiding question, nothing else.', '2026-11-01T10:26:38.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('bca46ec0-8031-415f-a39b-c9242d0ce7f4', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 8, 'Good question. It didnt hand us the conclusion.', '2026-11-01T10:29:28.000Z');
