INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('20504b6a-38a8-423b-a8fe-c4b884c256ee', 'ed1b895c-420f-4bff-a33b-32a9086ed110', 'final', 'P. Palat', 4, 3, 3, 3, 3, 3, 'Shared answer (19/24). More of the group''s own reasoning as the AI help gets lighter.', '2026-11-02T12:33:58.000Z', '2026-11-02T12:33:58.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('c21d8d41-638d-40ac-a145-086aedc87d1b', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-09', 9, 'The process is transparent: everyone writes down strengths and schedule limits first, before any topic is claimed. Then each person proposes two topics they can actually prepare, and we compare the set against an even workload. If we disagree, we return to those criteria instead of giving the topic to the most confident person. The hint was not needed; we hid it.', '[{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":115},{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":113},{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":137}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'e061052e-750f-4d10-a72e-cfe57e002a3a', '2026-11-01T10:37:08.000Z', '2026-11-01T10:48:18.000Z', 1, '2026-11-01T10:37:08.000Z', '2026-11-01T10:48:18.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('fc310615-cf4d-43b7-a46b-b7f7c910b453', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-09","scenarioOrder":9}', '2026-11-01T10:37:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('5dbe2683-d08a-495a-a41d-9d71aa0a5a0d', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 9, 'Four people, different strengths and schedules. Design the process, not the topics.', '2026-11-01T10:37:48.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('680d5700-b4af-4f6b-a134-daf050ce7557', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 9, 'First publish the constraints. Then people propose. Then we check workload.', '2026-11-01T10:38:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('4dd61ef3-6249-4544-a361-19113392e1a4', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 9, 'If we disagree, go back to the criteria instead of voting by confidence.', '2026-11-01T10:40:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('b7850c60-3325-444f-add7-f5d07711cbd2', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 9, 'I can take a hint only if we are actually stuck. I dont think we are.', '2026-11-01T10:41:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('b9d9b22f-fea4-40fc-ad17-faa0d4be66c7', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 9, 'Agreed. No AI on this one unless someone is blocked.', '2026-11-01T10:42:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('6b1640ff-7998-4810-a8fe-f1292cce71d6', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 9, 'Not blocked. Lets write.', '2026-11-01T10:43:08.000Z');
