INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('3c46b906-d69f-4790-abfa-5bde939aa19a', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'scenario-10', 10, 'Encourage AI that asks the group a question or gives a hint after a draft exists, because today that was enough once we knew the topic. Also encourage holding the answer until every member can explain it. Early on we could not, because the full answer arrived first. Avoid treating a full AI answer as the group''s work. A pasted paragraph looks finished and stops the discussion, which is the practice we would drop.', '[{"participantId":"a74f0b42-e6cc-4be4-a350-007a229019b8","length":136},{"participantId":"e9921b84-b421-4810-a448-41ac4fa961a3","length":131},{"participantId":"e061052e-750f-4d10-a72e-cfe57e002a3a","length":149}]', '["e9921b84-b421-4810-a448-41ac4fa961a3","e061052e-750f-4d10-a72e-cfe57e002a3a","a74f0b42-e6cc-4be4-a350-007a229019b8"]', 'a74f0b42-e6cc-4be4-a350-007a229019b8', '2026-11-01T10:51:28.000Z', '2026-11-01T11:03:58.000Z', 1, '2026-11-01T10:51:28.000Z', '2026-11-01T11:03:58.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('bad4b19f-dad2-4b01-a440-cd3aec0bd230', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'scenario_started', '{"scenarioId":"scenario-10","scenarioOrder":10}', '2026-11-01T10:51:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('1bc780d1-0295-4d11-a25a-16bfb0e3d329', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 10, 'Final one. One practice to encourage, one to avoid. I dont think we need AI.', '2026-11-01T10:51:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('11096ffc-c556-4e43-ab4e-ed3b1fb43ae4', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 10, 'Encourage private hints or questions. Avoid a full answer before the group has a draft.', '2026-11-01T10:52:58.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('ad212f05-11c2-48a1-ad7b-121e833883de', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 10, 'From today: early on the full answer was too much, and the later hints were enough.', '2026-11-01T10:54:08.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('c0292696-26ef-405b-a255-98a0cf41bdfd', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 10, 'Also encourage that everyone can explain the answer, because that is what we failed to do when we copied.', '2026-11-01T10:55:18.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('21e7dec5-b3e6-4e0e-a704-51faf5427b49', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 10, 'And avoid counting a pasted AI paragraph as a contribution.', '2026-11-01T10:56:28.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('f23745e2-b332-4dfc-a5e3-c3b3cce0a203', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 10, 'Ill write the encourage part, you two the avoid part.', '2026-11-01T10:57:28.000Z');
