INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('366e9cf0-31f2-4393-aff7-934c0e9dcb15', '3c46b906-d69f-4790-abfa-5bde939aa19a', 'final', 'P. Palat', 4, 4, 4, 3, 3, 4, 'Shared answer (22/24). More of the group''s own reasoning as the AI help gets lighter.', '2026-11-02T13:03:58.000Z', '2026-11-02T13:03:58.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('2b690b3c-8896-48d2-a2d7-09af325e10b5', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'post', '{"post-1":2,"post-2":0,"post-3":3,"post-4":1,"post-5":3,"post-6":1,"post-7":0,"post-8":2}', '{"open_collaboration":"Collaborative learning is building one answer everyone can explain, because the members need each other.","open_ai_role":"AI should scaffold with a hint or a question so the group still decides the answer."}', 8, 8, '2026-11-01T11:11:08.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('50e9f9c2-b0eb-4676-ae4c-b7a01da3326f', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'assessment_completed', '{"assessmentType":"post","score":8,"maxScore":8}', '2026-11-01T11:11:08.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('49f519f0-1801-42e1-a41a-16553c792043', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', '{"ai_effect_on_collaboration":"At the start it shortened the discussion, because the full answer arrived before we had finished talking. Later it got out of the way.","most_useful_support":"The guiding question, once we already had a direction. The full answer was useful only as a check.","unhelpful_or_too_much":"The full expert answer on the second and fourth tasks. It was too revealing and we nearly pasted it.","thinking_and_reliance":"Yes at the beginning. By the last tasks, no. We wrote the recommendation with no AI.","ai_into_group_answer":"Early on, yes, some sentences. Later I brought a question back to the chat instead of the wording.","private_vs_shared_ai":"Private worked, because I had to explain the idea to the others in the chat. Shared would have been tempting to copy.","participation":"Yes, more and more. On every answer all three of us wrote something.","agreement_on_answer":"Yes. On the early ones I agreed with the text more than with our own reasoning. On the last ones I agreed because we had argued it.","learned_most":"The amount of help should go down as the group understands more. Full answers feel good and teach less.","suggested_changes":"Keep the full answer available, but show it only after the group has a draft."}', '2026-11-01T11:17:08.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('ce938672-1d84-4866-a5f7-38d5b7cd9367', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e9921b84-b421-4810-a448-41ac4fa961a3', 'final_reflection_submitted', 'null', '2026-11-01T11:17:08.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('75c9f4ee-a128-4658-aa8c-a266d13f9c58', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 'post', '{"post-1":2,"post-2":0,"post-3":3,"post-4":1,"post-5":1,"post-6":1,"post-7":0,"post-8":2}', '{"open_collaboration":"It is collaborative when we question each other and agree on one answer, not when we paste sections together.","open_ai_role":"Ask for less direct help over time, and never submit the AI text unchanged."}', 7, 8, '2026-11-01T11:13:08.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('2fb6d06e-8ddf-4196-a12c-7cc5c2ad7f04', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 'assessment_completed', '{"assessmentType":"post","score":7,"maxScore":8}', '2026-11-01T11:13:08.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('b0c07d9b-e4d7-45cc-a051-22b27c02c488', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', '{"ai_effect_on_collaboration":"We talked more after we stopped asking for the full answer. Before that the chat was mostly about whether to copy it.","most_useful_support":"Feedback on our own draft. It pointed at a gap without writing the paragraph.","unhelpful_or_too_much":"Sometimes the full answer. I said so in the chat on task 2 and task 4.","thinking_and_reliance":"On the first four tasks it was close. After that I felt we were doing the thinking.","ai_into_group_answer":"I used one or two phrases early, then stopped. I said in the group what the idea was.","private_vs_shared_ai":"Private. If everyone saw the full answer, the chat would just be editing it.","participation":"Yes. We made sure each answer had all three names in it.","agreement_on_answer":"I clicked I am good when I could say the answer without looking. That was not true on task 2.","learned_most":"A higher score in a group can hide an unfair workload, and the same is true of an AI answer that looks finished.","suggested_changes":"The levels are good. I would add a reminder when the full answer is selected."}', '2026-11-01T11:18:08.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('4d56c241-b5ff-45a9-a87c-2d069f74ea4a', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'e061052e-750f-4d10-a72e-cfe57e002a3a', 'final_reflection_submitted', 'null', '2026-11-01T11:18:08.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('738fd5c4-9015-4ee1-abbd-a4ec87842ab3', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 'post', '{"post-1":2,"post-2":0,"post-3":3,"post-4":0,"post-5":1,"post-6":1,"post-7":0,"post-8":2}', '{"open_collaboration":"Collaborative means we question each other and can all explain the result, not divide the work and disappear.","open_ai_role":"Start with more help if we need it, then use less. Do not copy the AI."}', 6, 8, '2026-11-01T11:15:08.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('d820b498-55c9-46ce-a5fc-c66a715942e3', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 'assessment_completed', '{"assessmentType":"post","score":6,"maxScore":8}', '2026-11-01T11:15:08.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('448c6d92-2e70-4635-a3ac-8a89ffff8b47', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', '{"ai_effect_on_collaboration":"I spoke more in the second half. At the start Maria and Rafaella were comparing the full answer and I was quiet.","most_useful_support":"The small hint on the later tasks. I understood those.","unhelpful_or_too_much":"The full answer was too much for me. I could not tell which part was ours.","thinking_and_reliance":"A bit at the start. Not on the last task, we did not use AI at all.","ai_into_group_answer":"I tried not to. On the process task I even hid the hint because we were not stuck.","private_vs_shared_ai":"Private is better for me. I need to say the idea out loud or I dont learn it.","participation":"Yes by the end. I wrote part of every answer, even if my part was shorter at the beginning.","agreement_on_answer":"On the last tasks, yes. Earlier I agreed because the text sounded correct, not because it was mine.","learned_most":"I knew some of this before, but I can explain scaffolding better now: help should get smaller.","suggested_changes":"Nothing big. The decrease we did ourselves should maybe be suggested by the system."}', '2026-11-01T11:19:08.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('11589ff5-2b53-4342-a198-79b91a13be18', 'ae5aafcc-8d52-44e9-ae47-b1d3173ff348', 'a74f0b42-e6cc-4be4-a350-007a229019b8', 'final_reflection_submitted', 'null', '2026-11-01T11:19:08.000Z');
